from fractions import Fraction as F
rows=[('A',15,(1,0,0,1)),('A',9,(0,1,1,1)),('B',6,(1,0,0,0)),('B',5,(0,1,0,0)),('C',9,(1,1,1,1)),('C',5,(0,1,1,0)),('D',14,(0,0,0,0)),('D',9,(1,1,1,0))]
tests='TUVW'; modes='ABCD'
loss=[[0,24,11,6],[19,0,19,8],[9,10,0,16],[21,24,20,0]]
cost=list(map(F,['0.8','1.2','0.7','1.4']))
def stop(s):
 w=sum(rows[i][1] for i in s)
 return min((F(sum(rows[i][1]*loss[a][modes.index(rows[i][0])] for i in s),w),modes[a]) for a in range(4))
def solve(s,available,n):
 best=stop(s)
 if n:
  for t in available:
   v=buy(s,available,n,t)
   best=min(best,(v,tests[t]))
 return best
def buy(s,available,n,t):
 w=sum(rows[i][1] for i in s)
 v=cost[t]
 for b in [0,1]:
  sub=tuple(i for i in s if rows[i][2][t]==b)
  if sub:
   v+=F(sum(rows[i][1] for i in sub),w)*solve(sub,tuple(x for x in available if x!=t),n-1)[0]
 return v
s=tuple(range(8)); av=tuple(range(4))
vals={'STOP':float(stop(s)[0])}
vals.update({tests[t]:float(buy(s,av,2,t)) for t in av})
best=solve(s,av,2)
print(vals);print('optimal',best, float(best[0]))
if best[1] in tests:
 t=tests.index(best[1])
 for b in [0,1]:
  sub=tuple(i for i in s if rows[i][2][t]==b)
  print(b,solve(sub,tuple(x for x in av if x!=t),1))

